std::uint64_t bits(double x){return std::bit_cast<std::uint64_t>(x);}
bool same_cell(const c::Cell& x,const c::Cell& y){return bits(x.time_bounds[0])==bits(y.time_bounds[0])&&bits(x.time_bounds[1])==bits(y.time_bounds[1])&&x.depth==y.depth&&x.parent_audit==y.parent_audit;}
