std::array<const I*,15> intervals(const c::Evaluation& x){return {&x.first_coordinates[0],&x.first_coordinates[1],&x.first_coordinates[2],&x.second_coordinates[0],&x.second_coordinates[1],&x.second_coordinates[2],&x.delta[0],&x.delta[1],&x.delta[2],&x.raw_squared_distance,&x.nonnegative_squared_distance,&x.root.value,&x.distance,&x.threshold,&x.gap};}
bool same_interval(const I& x,const I& y){return bits(x.lower())==bits(y.lower())&&bits(x.upper())==bits(y.upper());}
struct Counts {std::size_t calls{},endpoints{},negative_zeros{},root_metadata{};};
Counts audit_provenance(const c::Result& result){
    // Public-value provenance only, including the two deliberately copied root
    // interval fields. Independent mathematics is a DIFFERENT acceptance gate.
    Counts counts;if(!result.snapshot){return counts;}
    for(const auto& audit:result.audits){if(!audit.evaluation){continue;}const auto repeated=c::value(result.snapshot->input,I{audit.cell.time_bounds[0],audit.cell.time_bounds[1]},result.snapshot->settings.sqrt_refinements);const auto actual=intervals(*audit.evaluation),expected=intervals(repeated);for(std::size_t i=0;i<actual.size();++i){for(unsigned end=0;end<2;++end){const double a0=end?actual[i]->upper():actual[i]->lower(),b0=end?expected[i]->upper():expected[i]->lower();require(bits(a0)==bits(b0),"All 15 Evaluation interval fields direct-value endpoint bits differ");++counts.endpoints;if(bits(a0)==0x8000000000000000ULL){++counts.negative_zeros;}}}require(audit.evaluation->root.refinements==repeated.root.refinements&&audit.evaluation->root.refinement_limited==repeated.root.refinement_limited,"Both root diagnostic fields replay exactly");counts.root_metadata+=2;++counts.calls;}
    return counts;
}
